// src/build/verify-build.ts
// Determinism / no-drift gate (run via `npm run build:verify`, wired into CI).
// Proves the committed scripts/ runtime is EXACTLY what a fresh buildRuntime()
// emits — i.e. nobody hand-edited scripts/, and no stale/orphan output lingers
// after a src/ change. Builds to a throwaway scratch dir, then compares every
// file against scripts/ by content hash. Two artifacts under scripts/ are NOT
// generated by buildRuntime and are excluded by design:
//   - lighthouse-runner.mjs        — legacy hand-authored ESM (dedicated emit pending)
//   - hook-runtime/**              — the transitional authoring-root marker stub
// (*.tsbuildinfo is excluded from both sides as an incremental-cache artifact.)
// Exits 1 with a precise drift report on any mismatch; 0 when scripts/ is the
// deterministic build output.

import { createHash } from 'crypto';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { buildRuntime } from './build-runtime';

const REPO_ROOT = path.resolve(__dirname, '..', '..');
const SCRIPTS = path.join(REPO_ROOT, 'scripts');

// scripts/ entries buildRuntime does NOT produce (so they can't be proven equal
// to a fresh build and must be skipped when walking the committed tree).
function isUngenerated(rel: string): boolean {
  return rel === 'lighthouse-runner.mjs'
    || rel === 'hook-runtime'
    || rel.startsWith('hook-runtime/')
    || rel.endsWith('.tsbuildinfo');
}

function hashTree(root: string, skip: (rel: string) => boolean): Map<string, string> {
  const out = new Map<string, string>();
  const rec = (dir: string): void => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const rel = path.relative(root, path.join(dir, entry.name)).split(path.sep).join('/');
      if (skip(rel)) continue;
      const abs = path.join(dir, entry.name);
      if (entry.isDirectory()) rec(abs);
      else if (entry.isFile()) out.set(rel, createHash('sha256').update(fs.readFileSync(abs)).digest('hex'));
    }
  };
  rec(root);
  return out;
}

function main(): void {
  const scratch = fs.mkdtempSync(path.join(os.tmpdir(), 't1-verify-build-'));
  try {
    buildRuntime(scratch);
    const fresh = hashTree(scratch, (rel) => rel.endsWith('.tsbuildinfo'));
    const committed = hashTree(SCRIPTS, isUngenerated);

    const drift: string[] = [];
    for (const [rel, hash] of fresh) {
      if (!committed.has(rel)) drift.push(`missing from scripts/ (build emits it):        ${rel}`);
      else if (committed.get(rel) !== hash) drift.push(`stale in scripts/ (differs from build):         ${rel}`);
    }
    for (const rel of committed.keys()) {
      if (!fresh.has(rel)) drift.push(`orphan in scripts/ (build no longer emits it):  ${rel}`);
    }

    if (drift.length > 0) {
      process.stderr.write(
        `verify-build: FAIL — committed scripts/ is not the deterministic build output:\n` +
        `${drift.map((d) => `  - ${d}`).join('\n')}\n` +
        `Run \`npm run build\` and commit the regenerated scripts/.\n`,
      );
      process.exit(1);
    }
    process.stdout.write(
      `verify-build: PASS — committed scripts/ is byte-identical to a fresh build ` +
      `(${committed.size} files compared; lighthouse-runner.mjs + authoring marker excluded by design).\n`,
    );
  } finally {
    fs.rmSync(scratch, { recursive: true, force: true });
  }
}

main();
